//! `setup` (M6 step 7): the real binary builds a Linux setup file from a release it packed, and the
//! file is read back the way the runtime reads it (`SetupTrailer::parse`, then `verify_setup`).
//! Keys are generated by the binary at test time; every command's output, and the setup file
//! itself, is scanned for every secret generated so far.

#![cfg(unix)]

mod common;

use std::cell::RefCell;
use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::process::Output;

use common::*;
use ed25519_dalek::SigningKey;
use ed25519_dalek::pkcs8::DecodePrivateKey;
use lunepack_codec_lzma::LzmaCodec;
use lunepack_core::setup::{SetupTrailer, TRAILER_MAGIC, TRAILER_SIZE, verify_setup};
use lunepack_core::{Clock, ClockReading, FsError, FsErrorKind, ReadAt};
use lunepack_crypto::{Ed25519Verifier, Sha256Hasher};
use lunepack_testkit::exe_headers;

const APP: &str = "org.example.hello";
const T0: u64 = 1_800_000_000;
const AT: u64 = T0 + 3600;
const VERSION: &str = "1.2.3";
const TARGET: &str = "linux-x86_64";

struct At(u64);

impl Clock for At {
    fn now_unix_secs(&self) -> u64 {
        self.0
    }
}

struct Bytes(Vec<u8>);

impl ReadAt for Bytes {
    fn size(&self) -> Result<u64, FsError> {
        Ok(self.0.len() as u64)
    }

    fn read_exact_at(&self, offset: u64, buf: &mut [u8]) -> Result<(), FsError> {
        let start = offset as usize;
        match self.0.get(start..start + buf.len()) {
            Some(src) => {
                buf.copy_from_slice(src);
                Ok(())
            }
            None => Err(FsError::new(FsErrorKind::Other, Path::new("setup"), None)),
        }
    }
}

fn s(path: &Path) -> &str {
    path.to_str().expect("utf-8 path")
}

const UPDATE_TOML: &str = r#"
[update]
feed = "https://updates.example.com/hello"
channel = "stable"
health_timeout_secs = 30

[install]
entry = "bin/app"
name = "Hello"
bin = "hello"
publisher = "Example Org"
"#;

/// A 64-bit little-endian static ELF (one `PT_LOAD`), then filler.
fn runtime_elf(machine: u16) -> Vec<u8> {
    let mut h = exe_headers::elf(machine, false, 64 + 56 + 4096);
    h[16..18].copy_from_slice(&3u16.to_le_bytes());
    h[32..40].copy_from_slice(&64u64.to_le_bytes());
    h[54..56].copy_from_slice(&56u16.to_le_bytes());
    h[56..58].copy_from_slice(&1u16.to_le_bytes());
    h[64..68].copy_from_slice(&1u32.to_le_bytes());
    h
}

/// A config, release keys, and one packed release `1.2.3` for `linux-x86_64` with a runtime.
struct World {
    dir: tempfile::TempDir,
    config: PathBuf,
    release: PathBuf,
    runtime: Vec<u8>,
    secrets: RefCell<Vec<Vec<u8>>>,
}

impl World {
    fn new() -> World {
        let dir = tempfile::tempdir().unwrap();
        let w = World {
            config: dir.path().join("lunepack.toml"),
            release: dir.path().join("rel"),
            runtime: runtime_elf(62),
            secrets: RefCell::new(Vec::new()),
            dir,
        };
        let root = w.new_key("root");
        let rel_key = w.new_key("release0");
        assert_ok(
            &w.run(&["init", "--app-id", APP, "--root-key", &root.1], &[]),
            "init",
        );
        {
            use std::io::Write as _;
            let mut f = fs::OpenOptions::new().append(true).open(&w.config).unwrap();
            f.write_all(UPDATE_TOML.as_bytes()).unwrap();
        }
        fs::create_dir(&w.release).unwrap();
        let root_spec = format!("file:{}", s(&root.0));
        let rel_spec = format!("file:{}", s(&rel_key.0));
        let out = w.run(
            &[
                "keys",
                "set",
                "--release-dir",
                s(&w.release),
                "--threshold",
                "1",
                "--release-key",
                &rel_key.1,
                "--sign",
                &root_spec,
            ],
            &[("SOURCE_DATE_EPOCH", &T0.to_string())],
        );
        assert_ok(&out, "keys set");

        let input = w.dir.path().join("input");
        let entry = input.join("bin/app");
        fs::create_dir_all(entry.parent().unwrap()).unwrap();
        fs::write(&entry, exe_headers::elf(62, false, 20_000)).unwrap();
        fs::set_permissions(&entry, fs::Permissions::from_mode(0o755)).unwrap();
        fs::create_dir_all(input.join("data")).unwrap();
        fs::write(input.join("data/readme.txt"), b"read me\n".repeat(400)).unwrap();
        let runtime = w.dir.path().join("runtime");
        fs::write(&runtime, &w.runtime).unwrap();
        let tmp = w.dir.path().join("tmp");
        fs::create_dir(&tmp).unwrap();
        let out = w.run(
            &[
                "pack",
                "--input",
                s(&input),
                "--version",
                VERSION,
                "--target",
                TARGET,
                "--release-dir",
                s(&w.release),
                "--sign",
                &rel_spec,
                "--runtime",
                s(&runtime),
            ],
            &[("SOURCE_DATE_EPOCH", &T0.to_string()), ("TMPDIR", s(&tmp))],
        );
        assert_ok(&out, "pack");
        w
    }

    fn cmd(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let output = run(args, env);
        let secrets = self.secrets.borrow();
        let refs: Vec<&[u8]> = secrets.iter().map(Vec::as_slice).collect();
        assert_no_secrets(&output, &refs);
        output
    }

    fn run(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let mut full = vec!["--config", s(&self.config)];
        full.extend_from_slice(args);
        self.cmd(&full, env)
    }

    /// A key file and its public key; the secret is remembered for the scans.
    fn new_key(&self, name: &str) -> (PathBuf, String) {
        let base = self.dir.path().join(name);
        let out = self.cmd(&["keys", "gen", s(&base)], &[]);
        assert_ok(&out, "keys gen");
        let path = base.with_extension("key");
        let pem = fs::read_to_string(&path).unwrap();
        let seed = SigningKey::from_pkcs8_pem(&pem).unwrap().to_bytes();
        let mut secrets = self.secrets.borrow_mut();
        secrets.push(pem.into_bytes());
        secrets.push(seed.to_vec());
        (path, field(&stdout(&out), "public:"))
    }

    fn setup(&self, out: &Path, extra: &[&str]) -> Output {
        let at = AT.to_string();
        let mut args = vec![
            "setup",
            s(&self.release),
            "--version",
            VERSION,
            "--target",
            TARGET,
            "--out",
            s(out),
            "--at",
            &at,
        ];
        args.extend_from_slice(extra);
        self.run(&args, &[])
    }

    fn release_file(&self, rel: &str) -> PathBuf {
        self.release.join(rel)
    }
}

/// Parses and verifies `bytes` as the runtime does, at `AT`.
fn check(bytes: &[u8]) -> Result<lunepack_core::setup::VerifiedSetup, String> {
    if (bytes.len() as u64) < TRAILER_SIZE {
        return Err("short".into());
    }
    let tail = &bytes[bytes.len() - TRAILER_SIZE as usize..];
    let trailer = SetupTrailer::parse(tail, bytes.len() as u64, &Sha256Hasher, &Ed25519Verifier)
        .map_err(|e| format!("trailer: {e}"))?;
    verify_setup(
        &trailer,
        &Bytes(bytes.to_vec()),
        &ClockReading::read(&At(AT), None),
        &LzmaCodec,
        &Sha256Hasher,
        &Ed25519Verifier,
    )
    .map_err(|e| format!("payload: {e}"))
}

fn trailer_of(bytes: &[u8]) -> SetupTrailer {
    let tail = &bytes[bytes.len() - TRAILER_SIZE as usize..];
    SetupTrailer::parse(tail, bytes.len() as u64, &Sha256Hasher, &Ed25519Verifier).unwrap()
}

#[test]
fn setup_writes_runtime_payload_and_trailer_deterministically() {
    let w = World::new();
    let a = w.dir.path().join("a-setup");
    let b = w.dir.path().join("b-setup");
    let out = w.setup(&a, &[]);
    assert_ok(&out, "setup");
    assert!(
        stdout(&out).starts_with("setup: a-setup ("),
        "{}",
        stdout(&out)
    );
    assert_ok(&w.setup(&b, &[]), "setup again");
    let bytes = fs::read(&a).unwrap();
    assert_eq!(bytes, fs::read(&b).unwrap(), "two runs differ");
    assert_eq!(
        fs::metadata(&a).unwrap().permissions().mode() & 0o777,
        0o755
    );

    // runtime ‖ key set ‖ manifest ‖ pack ‖ trailer, each part 8-byte aligned.
    assert!(bytes.starts_with(&w.runtime));
    assert!(bytes.ends_with(&TRAILER_MAGIC));
    let t = trailer_of(&bytes);
    let part = |p: lunepack_core::setup::SetupPart| {
        assert_eq!(p.offset % 8, 0);
        bytes[p.offset as usize..(p.offset + p.length) as usize].to_vec()
    };
    assert_eq!(part(t.keys), fs::read(w.release_file("keys.json")).unwrap());
    assert_eq!(
        part(t.manifest),
        fs::read(w.release_file(&format!("{VERSION}/{TARGET}.manifest.json"))).unwrap()
    );
    assert_eq!(
        part(t.pack),
        fs::read(w.release_file(&format!("{VERSION}/{TARGET}.pack"))).unwrap()
    );
    assert!(t.keys.offset >= w.runtime.len() as u64);
    assert_eq!(t.version.to_string(), VERSION);
    assert_eq!(t.target.as_str(), TARGET);
    assert_eq!(t.root.app_id().as_str(), APP);

    let verified = check(&bytes).expect("the setup verifies");
    assert_eq!(verified.config.install.name, "Hello");
    assert_eq!(
        verified.config.install.publisher.as_deref(),
        Some("Example Org")
    );
    assert!(verified.installed_bytes() > 0);

    // No key material: only the public root goes into the file.
    let secrets = w.secrets.borrow();
    let refs: Vec<&[u8]> = secrets.iter().map(Vec::as_slice).collect();
    assert_no_secrets(
        &Output {
            status: out.status,
            stdout: bytes,
            stderr: Vec::new(),
        },
        &refs,
    );
}

#[test]
fn an_existing_output_and_a_non_linux_target_are_refused() {
    let w = World::new();
    let a = w.dir.path().join("a-setup");
    fs::write(&a, b"keep").unwrap();
    let err = assert_fails(&w.setup(&a, &[]), 1, "existing out");
    assert!(err.contains("already exists"), "{err}");
    assert_eq!(fs::read(&a).unwrap(), b"keep");

    let b = w.dir.path().join("b-setup");
    let at = AT.to_string();
    let out = w.run(
        &[
            "setup",
            s(&w.release),
            "--version",
            VERSION,
            "--target",
            "windows-x86_64",
            "--out",
            s(&b),
            "--at",
            &at,
        ],
        &[],
    );
    let err = assert_fails(&out, 1, "windows target");
    assert!(err.contains("Linux targets only"), "{err}");
    assert!(!b.exists());
    // A version the release does not hold.
    let out = w.run(
        &[
            "setup",
            s(&w.release),
            "--version",
            "9.9.9",
            "--target",
            TARGET,
            "--out",
            s(&b),
            "--at",
            &at,
        ],
        &[],
    );
    assert_fails(&out, 1, "absent version");
    assert!(!b.exists());
}

#[test]
fn a_tampered_release_file_is_refused_before_writing() {
    for rel in [
        "keys.json".to_owned(),
        format!("{VERSION}/{TARGET}.manifest.json"),
        format!("{VERSION}/{TARGET}.pack"),
    ] {
        let w = World::new();
        let path = w.release_file(&rel);
        let mut bytes = fs::read(&path).unwrap();
        let mid = bytes.len() / 2;
        bytes[mid] ^= 0x01;
        fs::write(&path, bytes).unwrap();
        let out_path = w.dir.path().join("setup");
        assert_fails(&w.setup(&out_path, &[]), 1, &rel);
        assert!(!out_path.exists(), "{rel}: a file was written");
    }
}

#[test]
fn the_runtime_check_refuses_a_tampered_truncated_or_overlapping_file() {
    let w = World::new();
    let a = w.dir.path().join("a-setup");
    assert_ok(&w.setup(&a, &[]), "setup");
    let bytes = fs::read(&a).unwrap();
    let t = trailer_of(&bytes);

    // One flipped byte in each part.
    for (name, p) in [("keys", t.keys), ("manifest", t.manifest), ("pack", t.pack)] {
        let mut b = bytes.clone();
        b[(p.offset + p.length / 2) as usize] ^= 0x01;
        assert!(check(&b).is_err(), "{name}");
    }
    // Truncated: a byte short, or the trailer gone.
    assert!(check(&bytes[..bytes.len() - 1]).is_err());
    let mut cut = bytes[..bytes.len() - TRAILER_SIZE as usize - 1].to_vec();
    cut.extend_from_slice(&bytes[bytes.len() - TRAILER_SIZE as usize..]);
    assert!(check(&cut).is_err(), "a payload byte short");
    // Overlapping parts: the manifest moved into the key set.
    let mut moved = t.clone();
    moved.manifest.offset = t.keys.offset + 8;
    let mut b = bytes[..bytes.len() - TRAILER_SIZE as usize].to_vec();
    b.extend_from_slice(&moved.encode().unwrap());
    let err = check(&b).unwrap_err();
    assert!(err.contains("overlap"), "{err}");
    // A trailer whose root is not the one the config names (another key, same app).
    let other = lunepack_core::TrustedRoot::from_parts(
        t.root.app_id().clone(),
        1,
        1,
        &[[7u8; 32]],
        &Sha256Hasher,
        &Ed25519Verifier,
    );
    if let Ok(other) = other {
        let mut swapped = t.clone();
        swapped.root = other;
        let mut b = bytes[..bytes.len() - TRAILER_SIZE as usize].to_vec();
        b.extend_from_slice(&swapped.encode().unwrap());
        assert!(check(&b).is_err(), "another root");
    }
    // A wrong target in the trailer.
    let mut wrong = t.clone();
    wrong.target = lunepack_core::Target::LinuxAarch64;
    let mut b = bytes[..bytes.len() - TRAILER_SIZE as usize].to_vec();
    b.extend_from_slice(&wrong.encode().unwrap());
    let err = check(&b).unwrap_err();
    assert!(err.contains("target"), "{err}");
    // Untouched, it verifies.
    check(&bytes).unwrap();
}
